extract_latest_proximity.text:
for name in ordered_names:
    value = np.asarray(obs[name], dtype=np.float32)
    if value.shape == EXPECTED_PATCH_SHAPE:
        latest = value
    elif value.ndim == 3 and value.shape[0] >= 1 and value.shape[1:] == EXPECTED_PATCH_SHAPE:
        latest = value[-1]
    else:
        raise HybridSafetyContractError(
            f"Sensor {name} has shape {value.shape}; expected (8, 8) or (N, 8, 8)"
        )
    if not np.isfinite(latest).all():
        raise HybridSafetyContractError(f"Sensor {name} contains non-finite depth")
    frames.append(latest)
return np.stack(frames, axis=0).astype(np.float32, copy=False)

